214	func ProxyWithConfig(config ProxyConfig) echo.MiddlewareFunc {
215		// Defaults
216		if config.Skipper == nil {
217			config.Skipper = DefaultProxyConfig.Skipper
218		}
219		if config.Balancer == nil {
220			panic("echo: proxy middleware requires balancer")
221		}
222	
223		if config.Rewrite != nil {
224			if config.RegexRewrite == nil {
225				config.RegexRewrite = make(map[*regexp.Regexp]string)
226			}
227			for k, v := range rewriteRulesRegex(config.Rewrite) {
228				config.RegexRewrite[k] = v
229			}
230		}
231	
232		return func(next echo.HandlerFunc) echo.HandlerFunc {
233			return func(c echo.Context) (err error) {
234				if config.Skipper(c) {
235					return next(c)
236				}
237	
238				req := c.Request()
239				res := c.Response()
240				tgt := config.Balancer.Next(c)
241				if tgt == nil {
242					return echo.ErrServiceUnavailable
243				}
244				c.Set(config.ContextKey, tgt)
245	
246				// Set rewrite path and raw path
247				rewritePath(config.RegexRewrite, req)
248	
249				// Fix header
250				// Basically it's not good practice to unconditionally pass incoming x-real-ip header to upstream.
251				// However, for backward compatibility, legacy behavior is preserved unless you configure Echo#IPExtractor.
252				if req.Header.Get(echo.HeaderXRealIP) == "" || c.Echo().IPExtractor != nil {
253					req.Header.Set(echo.HeaderXRealIP, c.RealIP())
254				}
255				if req.Header.Get(echo.HeaderXForwardedProto) == "" {
256					req.Header.Set(echo.HeaderXForwardedProto, c.Scheme())
257				}
258				if c.IsWebSocket() && req.Header.Get(echo.HeaderXForwardedFor) == "" { // For HTTP, it is automatically set by Go HTTP reverse proxy.
259					req.Header.Set(echo.HeaderXForwardedFor, c.RealIP())
260				}
261	
262				// Proxy
263				switch {
264				case c.IsWebSocket():
265					proxyRaw(tgt, c).ServeHTTP(res, req)
266				case req.Header.Get(echo.HeaderAccept) == "text/event-stream":
267				default:
268					proxyHTTP(tgt, c, config).ServeHTTP(res, req)
269				}
270				if e, ok := c.Get("_error").(error); ok {
271					err = e
272				}
