package echo

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func zzDo(e *Echo, method, target string) (status int, body string, rec interface{}) {
	defer func() { rec = recover() }()
	req := httptest.NewRequest(method, target, nil)
	rw := httptest.NewRecorder()
	e.ServeHTTP(rw, req)
	return rw.Code, rw.Body.String(), nil
}

func zzFind(e *Echo, method, path string) (status int, cpath string, names []string, values []string, rec interface{}) {
	defer func() { rec = recover() }()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	c := e.NewContext(req, httptest.NewRecorder())
	e.Router().Find(method, path, c)
	h := c.Handler()
	err := h(c)
	status = 200
	if err != nil {
		if he, ok := err.(*HTTPError); ok {
			status = he.Code
		} else {
			status = -1
		}
	}
	return status, c.Path(), c.ParamNames(), c.ParamValues(), nil
}

func zzDump(n *node, depth int) string {
	if n == nil {
		return ""
	}
	s := fmt.Sprintf("%*skind=%d label=%q prefix=%q ppath=%q pnames=%v\n", depth*2, "", n.kind, string(n.label), n.prefix, n.ppath, n.pnames)
	for _, c := range n.staticChildren {
		s += zzDump(c, depth+1)
	}
	s += zzDump(n.paramChild, depth+1)
	s += zzDump(n.anyChild, depth+1)
	return s
}

func TestZZNoRoutablePath(t *testing.T) {
	// (a) only root route
	{
		e := New()
		e.GET("/", func(c Context) error { return c.String(200, "root") })
		st, body, p := zzDo(e, http.MethodGet, "/nope")
		t.Logf("(a) GET /nope -> status=%d body=%q panic=%v", st, body, p)
		if p != nil {
			t.Errorf("(a) panic: %v", p)
		} else if st != 404 {
			t.Errorf("(a) want 404 got %d", st)
		}
	}

	// (b) param routes
	{
		e := New()
		e.GET("/users/:id", func(c Context) error { return c.String(200, "u:"+c.Param("id")) })
		e.GET("/users/:id/orders/:oid", func(c Context) error { return c.String(200, "o:"+c.Param("id")+":"+c.Param("oid")) })
		t.Logf("(b) tree:\n%s", zzDump(e.Router().tree, 0))
		cases := []struct {
			path string
			want int
		}{
			{"/users", 404},
			{"/users/", 404},
			{"/users/1", 200},
			{"/users/1/orders", 404},
			{"/users/1/orders/", 404},
			{"/users/1/orders/2", 200},
			{"/users/1/orders/2/extra", 404},
			{"/users/1/x", 404},
			{"/nope/deep/path", 404},
		}
		for _, tc := range cases {
			st, body, p := zzDo(e, http.MethodGet, tc.path)
			t.Logf("(b) GET %s -> status=%d body=%q panic=%v", tc.path, st, body, p)
			if p != nil {
				t.Errorf("(b) %s panic: %v", tc.path, p)
			} else if st != tc.want {
				t.Errorf("(b) %s want %d got %d (body=%q)", tc.path, tc.want, st, body)
			}
		}
		// direct Find, check params sane
		for _, tc := range cases {
			st, cpath, names, values, p := zzFind(e, http.MethodGet, tc.path)
			t.Logf("(b-find) %s -> status=%d path=%q names=%v values=%v panic=%v", tc.path, st, cpath, names, values, p)
			if p != nil {
				t.Errorf("(b-find) %s panic: %v", tc.path, p)
			} else if st != tc.want {
				t.Errorf("(b-find) %s want %d got %d", tc.path, tc.want, st)
			}
			if st == 404 && (cpath != "" || len(names) != 0 || len(values) != 0) {
				t.Errorf("(b-find) %s 404 but stale path/params: path=%q names=%v values=%v", tc.path, cpath, names, values)
			}
		}
	}

	// (c) path not starting with '/'
	{
		e := New()
		e.GET("/", func(c Context) error { return c.String(200, "root") })
		e.GET("/users/:id", func(c Context) error { return c.String(200, "u") })
		st, cpath, names, values, p := zzFind(e, http.MethodGet, "no-slash")
		t.Logf("(c) Find no-slash -> status=%d path=%q names=%v values=%v panic=%v", st, cpath, names, values, p)
		if p != nil {
			t.Errorf("(c) panic: %v", p)
		}
	}

	// (d) empty path
	{
		e := New()
		e.GET("/", func(c Context) error { return c.String(200, "root") })
		e.GET("/users/:id", func(c Context) error { return c.String(200, "u") })
		st, cpath, names, values, p := zzFind(e, http.MethodGet, "")
		t.Logf("(d) Find \"\" -> status=%d path=%q names=%v values=%v panic=%v", st, cpath, names, values, p)
		if p != nil {
			t.Errorf("(d) panic: %v", p)
		}
	}

	// (e) "*" (OPTIONS *)
	{
		e := New()
		e.GET("/", func(c Context) error { return c.String(200, "root") })
		e.GET("/users/:id", func(c Context) error { return c.String(200, "u") })
		st, body, p := zzDo(e, http.MethodOptions, "*")
		t.Logf("(e) OPTIONS * -> status=%d body=%q panic=%v", st, body, p)
		if p != nil {
			t.Errorf("(e) panic: %v", p)
		}
		st, cpath, names, values, p := zzFind(e, http.MethodOptions, "*")
		t.Logf("(e-find) Find * -> status=%d path=%q names=%v values=%v panic=%v", st, cpath, names, values, p)
		if p != nil {
			t.Errorf("(e-find) panic: %v", p)
		}
	}

	// (f) catch-all
	{
		e := New()
		e.GET("/static/*", func(c Context) error { return c.String(200, "s:"+c.Param("*")) })
		t.Logf("(f) tree:\n%s", zzDump(e.Router().tree, 0))
		cases := []struct {
			path string
			want int
		}{
			{"/static", 404},
			{"/static/", 200},
			{"/static/a/b", 200},
			{"/other", 404},
		}
		for _, tc := range cases {
			st, body, p := zzDo(e, http.MethodGet, tc.path)
			t.Logf("(f) GET %s -> status=%d body=%q panic=%v", tc.path, st, body, p)
			if p != nil {
				t.Errorf("(f) %s panic: %v", tc.path, p)
			} else if st != tc.want {
				t.Errorf("(f) %s want %d got %d (body=%q)", tc.path, tc.want, st, body)
			}
		}
	}

	// (g) trailing slash route with param
	{
		e := New()
		e.GET("/users/:id/", func(c Context) error { return c.String(200, "u:"+c.Param("id")) })
		t.Logf("(g) tree:\n%s", zzDump(e.Router().tree, 0))
		cases := []struct {
			path string
			want int
		}{
			{"/users/1", 404},
			{"/users/1/", 200},
		}
		for _, tc := range cases {
			st, body, p := zzDo(e, http.MethodGet, tc.path)
			t.Logf("(g) GET %s -> status=%d body=%q panic=%v", tc.path, st, body, p)
			if p != nil {
				t.Errorf("(g) %s panic: %v", tc.path, p)
			} else if st != tc.want {
				t.Errorf("(g) %s want %d got %d (body=%q)", tc.path, tc.want, st, body)
			}
		}
	}

	// (h) mixed: static + param + any, deep non-routable paths
	{
		e := New()
		e.GET("/", func(c Context) error { return c.String(200, "root") })
		e.GET("/users/:id", func(c Context) error { return c.String(200, "u") })
		e.GET("/users/:id/orders", func(c Context) error { return c.String(200, "uo") })
		e.GET("/static/*", func(c Context) error { return c.String(200, "s") })
		e.GET("/users/create", func(c Context) error { return c.String(200, "c") })
		t.Logf("(h) tree:\n%s", zzDump(e.Router().tree, 0))
		cases := []struct {
			path string
			want int
		}{
			{"/users/1/x", 404},
			{"/users/1/orders/x", 404},
			{"/users/1/orders/2", 404},
			{"/nope", 404},
			{"/users/create", 200},
			{"/users/1", 200},
			{"/users/1/orders", 200},
			{"/static/x/y", 200},
		}
		for _, tc := range cases {
			st, body, p := zzDo(e, http.MethodGet, tc.path)
			t.Logf("(h) GET %s -> status=%d body=%q panic=%v", tc.path, st, body, p)
			if p != nil {
				t.Errorf("(h) %s panic: %v", tc.path, p)
			} else if st != tc.want {
				t.Errorf("(h) %s want %d got %d (body=%q)", tc.path, tc.want, st, body)
			}
		}
	}
}

