// ---- oracle ----

type patSeg struct {
	kind int // 0 static, 1 param, 2 any
	text string
}

func parsePattern(p string) []patSeg {
	parts := strings.Split(p, "/")
	segs := make([]patSeg, 0, len(parts))
	for _, s := range parts {
		switch {
		case s == "*":
			segs = append(segs, patSeg{2, "*"})
		case strings.HasPrefix(s, ":"):
			segs = append(segs, patSeg{1, s[1:]})
		default:
			segs = append(segs, patSeg{0, s})
		}
	}
	return segs
}

func kindStr(segs []patSeg) string {
	out := ""
	for _, s := range segs {
		out += fmt.Sprint(s.kind)
	}
	return out
}

// matchPattern: echo semantics. `*` consumes the whole remaining path (pattern after `*` is ignored).
func matchPattern(segs []patSeg, path string) (map[string]string, bool) {
	parts := strings.Split(path, "/")
	params := map[string]string{}
	i := 0
	for _, seg := range segs {
		switch seg.kind {
		case 0:
			if i >= len(parts) || parts[i] != seg.text {
				return nil, false
			}
			i++
		case 1:
			if i >= len(parts) {
				return nil, false
			}
			if i == len(parts)-1 && parts[i] == "" {
				return nil, false
			}
			params[seg.text] = parts[i]
			i++
		case 2:
			if i >= len(parts) {
				return nil, false
			}
			params["*"] = strings.Join(parts[i:], "/")
			return params, true
		}
	}
	if i != len(parts) {
		return nil, false
	}
	return params, true
}

func lessKinds(a, b []patSeg) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i].kind != b[i].kind {
			return a[i].kind < b[i].kind
		}
	}
	return len(a) < len(b)
}

func oracle(routes []string, path string) (string, map[string]string, bool) {
	var best []patSeg
	var bestParams map[string]string
	for _, rt := range routes {
		segs := parsePattern(rt)
		params, ok := matchPattern(segs, path)
		if !ok {
			continue
		}
		if best == nil || lessKinds(segs, best) {
			best = segs
			bestParams = params
		}
	}
	if best == nil {
		return "", nil, false
	}
	return kindStr(best), bestParams, true
}

func TestZZOracleFuzz(t *testing.T) {
	routePool := []string{
		"/", "/a", "/a/b", "/a/b/c", "/a/:p", "/a/:p/b", "/a/:p/:q", "/:p", "/:p/b",
		"/a/*", "/*", "/a/:p/*", "/a/b/:p", "/a/:p/b/:q", "/x/y/z", "/:p/:q",
		"/static/*", "/static/:p", "/a/:p/", "/:p/", "/a/b/", "/a/:p/b/", "/a/:p/*/",
		"/a/b/c/d", "/:p/b/c", "/a/:p/c", "/x/:p", "/x/:p/y", "/x/*", "/a/b/*",
	}
	paths := []string{
		"", "/", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/", "/a/b/c/d",
		"/x", "/x/y", "/x/y/z", "/x/y/z/w", "/a/1", "/a/1/", "/a/1/b", "/a/1/b/",
		"/a/1/b/2", "/a/1/b/2/3", "/a/1/2", "/1", "/1/b", "/static", "/static/",
		"/static/a/b", "no-slash", "*", "//", "/a//b", "/a/1//2", "/a/1/b/2/3/4",
		"/a/b/c/d/e", "/x/1/y/z", "/x/1/2", "/a/b/c/", "/a/b//c",
	}
	seed := uint64(999)
	rnd := func(n int) int {
		seed = seed*6364136223846793005 + 1442695040888963407
		return int((seed >> 33) % uint64(n))
	}
	bad := map[string]string{}
	for iter := 0; iter < 3000; iter++ {
		n := 1 + rnd(4)
		var routes []string
		for i := 0; i < n; i++ {
			routes = append(routes, routePool[rnd(len(routePool))])
		}
		e := New()
		for _, rt := range routes {
			e.GET(rt, func(c Context) error { return c.String(200, "ok") })
		}
		for _, p := range paths {
			st, cpath, names, values, rec := zzFind(e, http.MethodGet, p)
			if rec != nil {
