					bad[key] = key
					continue
				}
				for k, v := range wantParams {
					found := false
					for i, nm := range names {
						if nm == k {
							found = true
							if values[i] != v {
								key := fmt.Sprintf("PARAM routes=%v path=%q param %q: find=%q oracle=%q", routes, p, k, values[i], v)
								bad[key] = key
							}
						}
					}
					if !found {
						key := fmt.Sprintf("PARAMMISSING routes=%v path=%q param %q oracle=%q findnames=%v", routes, p, k, v, names)
						bad[key] = key
					}
				}
			}
		}
	}
	i := 0
	for k := range bad {
		t.Errorf("%s", k)
		i++
		if i > 30 {
			break
		}
	}
	t.Logf("total bad=%d", len(bad))
}
