package middleware

import (
	"bytes"
	"compress/gzip"
	"io/ioutil"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/labstack/echo/v4"
)

// helper: run handler h through Gzip() middleware with Accept-Encoding gzip and
// verify the resulting response is decodable.
func checkGzipEmpty(t *testing.T, name string, h echo.HandlerFunc) {
	t.Helper()
	e := echo.New()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)
	mw := Gzip()(h)
	if err := mw(c); err != nil {
		t.Errorf("[%s] handler returned error: %v", name, err)
		return
	}
	res := rec.Result()
	ce := res.Header.Get(echo.HeaderContentEncoding)
	body := rec.Body.Bytes()
	t.Logf("[%s] status=%d CE=%q bodyLen=%d body=%q CL=%q", name, res.StatusCode, ce, len(body), body, res.Header.Get("Content-Length"))
	if ce == gzipScheme {
		zr, err := gzip.NewReader(bytes.NewReader(body))
		if err != nil {
			t.Errorf("[%s] gzip.NewReader failed: %v (body=%q)", name, err, body)
			return
		}
		out, err := ioutil.ReadAll(zr)
		if err != nil {
			t.Errorf("[%s] gunzip read failed: %v (body=%q)", name, err, body)
			return
		}
		if len(out) != 0 {
			t.Errorf("[%s] expected empty decompressed body, got %q", name, out)
		}
	} else {
		if len(body) != 0 {
			t.Errorf("[%s] expected empty body when not compressed, got %q", name, body)
		}
	}
	if cl := res.Header.Get("Content-Length"); cl != "" {
		if cl != itoa(len(body)) {
			t.Errorf("[%s] Content-Length %q inconsistent with body len %d", name, cl, len(body))
		}
	}
}

func itoa(i int) string {
	return string([]byte{byte('0' + i/10%10), byte('0' + i%10)})[boolToInt(i < 10):]
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

func TestZZGzipEmpty(t *testing.T) {
	// 1. handler writes nothing at all
	checkGzipEmpty(t, "nothing", func(c echo.Context) error { return nil })

	// 2. handler writes an empty byte slice explicitly
	checkGzipEmpty(t, "write-empty-slice", func(c echo.Context) error {
		c.Response().Write([]byte(""))
		return nil
	})

	// 3. 204 + empty write
	checkGzipEmpty(t, "204-empty-write", func(c echo.Context) error {
		c.Response().WriteHeader(http.StatusNoContent)
		c.Response().Write([]byte(""))
		return nil
	})

	// 3b. 204 via c.NoContent
	checkGzipEmpty(t, "204-nocontent", func(c echo.Context) error {
		return c.NoContent(http.StatusNoContent)
	})

	// 4. non-empty body sanity
	checkGzipEmpty(t, "non-empty", func(c echo.Context) error {
		c.Response().Write([]byte("test"))
		return nil
	})

	// 5. c.String(200, "") -> commits header before empty write
	checkGzipEmpty(t, "c.String-empty", func(c echo.Context) error {
		return c.String(http.StatusOK, "")
	})

	// 6. explicit WriteHeader(200) then empty write
	checkGzipEmpty(t, "WriteHeader200-empty-write", func(c echo.Context) error {
		c.Response().WriteHeader(http.StatusOK)
		c.Response().Write([]byte(""))
		return nil
	})

	// 7. c.JSON(200, "") ... empty JSON string
	checkGzipEmpty(t, "c.JSON-empty-string", func(c echo.Context) error {
		return c.JSON(http.StatusOK, "")
	})

	// 8. 204 must not be compressed at all
	e := echo.New()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)
	h := Gzip()(func(c echo.Context) error {
		c.Response().WriteHeader(http.StatusNoContent)
		c.Response().Write([]byte(""))
		return nil
	})
	if err := h(c); err != nil {
		t.Fatal(err)
	}
	if got := rec.Result().Header.Get(echo.HeaderContentEncoding); got != "" {
		t.Errorf("[204] expected no Content-Encoding, got %q", got)
	}
	if rec.Body.Len() != 0 {
		t.Errorf("[204] expected empty body, got %q", rec.Body.Bytes())
	}
}
