			s += "/"
		}
		return s
	}
	panics := map[string]string{}
	for iter := 0; iter < 20000; iter++ {
		n := 1 + rnd(5)
		routes := make([]string, 0, n)
		for i := 0; i < n; i++ {
			routes = append(routes, genRoute())
