			defer func() {
				if p := recover(); p != nil {
					key := fmt.Sprintf("ADD routes=%q panic=%v", routes, p)
					panics[key] = key
				}
			}()
			for _, rt := range routes {
				e.GET(rt, func(c Context) error { return c.String(200, "ok") })
			}
