		paths := []string{"", "/", "*", "no-slash", "//", "/a/b/c/d/e"}
		for i := 0; i < 6; i++ {
			paths = append(paths, genPath())
		}
		for _, p := range paths {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						key := fmt.Sprintf("FIND routes=%q path=%q panic=%v", routes, p, rec)
						panics[key] = key
					}
				}()
				zzFind(e, http.MethodGet, p)
			}()
		}
	}
	i := 0
	for k := range panics {
		t.Errorf("%s", k)
		i++
		if i > 20 {
			break
		}
	}
	t.Logf("total panics=%d", len(panics))
}
